"""Generated by the NL to Flow Diagram Encoder Pipeline."""

numlist = [7, 9, 3, 5, 2.6, 8.3]

total = 0

counter = 0

while (len(numlist) > 0):
    total = (total + numlist.pop(0))
    counter = (counter + 1)

average = (total / counter)

total = format(total, '.2f')

average = format(average, '.2f')

